import analyze as A
import z3
import stress_feas as SF
from math import gcd
def lcm(a,b): return a//gcd(a,b)*b

def prep(norm):
    nodes=norm['nodes']; edges=norm['edges']; edge_ids=norm['edge_ids']; edge_index=norm['edge_index']
    commodities=norm['commodities']; comm_ids=norm['comm_ids']; domains=norm['domains']; snaps=norm['snapshots']
    nc=len(comm_ids); ne=len(edge_ids); ns=len(snaps); nd=len(domains)
    W=[sum(w for (_,w) in c['routes']) for c in commodities]
    L=1
    for w in W: L=lcm(L,w)
    coeff=[[0]*ne for _ in range(nc)]
    for ci,c in enumerate(commodities):
        wc=W[ci]
        for (ed,w) in c['routes']:
            add=L*w//wc
            for eid in ed: coeff[ci][edge_index[eid]]+=add
    return dict(nodes=nodes,edges=edges,edge_ids=edge_ids,edge_index=edge_index,commodities=commodities,comm_ids=comm_ids,domains=domains,snaps=snaps,nc=nc,ne=ne,ns=ns,nd=nd,L=L,coeff=coeff,W=W)

def ve(B,s,metric,target):
    nc=B['nc'];L=B['L'];q=B['q'][s];comm_ids=B['comm_ids'];coeff=B['coeff'];edge_index=B['edge_index'];commodities=B['commodities']
    if metric=='demand': return L*q[comm_ids.index(target)]
    if metric=='link':
        e=edge_index[target]; expr=None
        for ci in range(nc):
            cf=coeff[ci][e]
            if cf:
                t=cf*q[ci]; expr=t if expr is None else expr+t
        return expr if expr is not None else z3.IntVal(0)
    expr=None
    for ci,c in enumerate(commodities):
        if (metric=='ingress' and c['source']==target) or (metric=='egress' and c['target']==target):
            t=L*q[ci]; expr=t if expr is None else expr+t
    return expr if expr is not None else z3.IntVal(0)

def build_base(B):
    nc=B['nc'];ne=B['ne'];ns=B['ns'];L=B['L'];coeff=B['coeff'];snaps=B['snaps'];edges=B['edges']
    B['q']=[[z3.Int('q_%d_%d'%(s,c)) for c in range(nc)] for s in range(ns)]
    base=[]
    for s in range(ns):
        for ci in range(nc):
            lo,hi=snaps[s]['bounds'][ci]; base+=[B['q'][s][ci]>=lo,B['q'][s][ci]<=hi]
    for s in range(ns):
        for e in range(ne):
            cap=edges[e]['capacity']; expr=None
            for ci in range(nc):
                cf=coeff[ci][e]
                if cf:
                    t=cf*B['q'][s][ci]; expr=t if expr is None else expr+t
            if expr is not None: base.append(expr<=L*cap)
    return base

def get_k(B):
    nd=B['nd'];domains=B['domains'];snaps=B['snaps'];ns=B['ns']
    faulty=[z3.Bool('f_%d'%d) for d in range(nd)]
    base=list(build_base(B))
    for s in range(ns):
        for o in snaps[s]['observations']:
            expr=ve(B,s,o['metric'],o['target']); loL=B['L']*o['lo'];hiL=B['L']*o['hi']
            inside=z3.And(expr>=loL,expr<=hiL)
            if o['domain'] is None: base.append(inside)
            else: base.append(z3.Or(inside,faulty[domains.index(o['domain'])]))
    sumf=z3.Sum([z3.If(f,1,0) for f in faulty]) if nd>0 else z3.IntVal(0)
    o=z3.Optimize(); o.add(base); h=o.minimize(sumf); r=o.check()
    if r!=z3.sat: return None,None
    return o.lower(h).as_long(), faulty

def snapshot_solver(B,S,sigdomains):
    # build pure LIA solver for snapshot s with relaxed set given as set of domain indices
    nc=B['nc'];ne=B['ne'];L=B['L'];coeff=B['coeff'];snaps=B['snaps'];edges=B['edges'];domains=B['domains']
    qs=[z3.Int('y_%d'%ci) for ci in range(nc)]
    cons=[]
    for ci in range(nc):
        lo,hi=snaps[s]['bounds'][ci]; cons+=[qs[ci]>=lo,qs[ci]<=hi]
    for e in range(ne):
        cap=edges[e]['capacity']; expr=None
        for ci in range(nc):
            cf=coeff[ci][e]
            if cf:
                t=cf*qs[ci]; expr=t if expr is None else expr+t
        if expr is not None: cons.append(expr<=L*cap)
    # ve local
    def ve2(metric,target):
        if metric=='demand': return L*qs[B['comm_ids'].index(target)]
        if metric=='link':
            e=B['edge_index'][target]; expr=None
            for ci in range(nc):
                cf=coeff[ci][e]
                if cf:
                    t=cf*qs[ci]; expr=t if expr is None else expr+t
            return expr if expr is not None else z3.IntVal(0)
        expr=None
        for ci,c in enumerate(B['commodities']):
            if (metric=='ingress' and c['source']==target) or (metric=='egress' and c['target']==target):
                t=L*qs[ci]; expr=t if expr is None else expr+t
        return expr if expr is not None else z3.IntVal(0)
    for o in snaps[s]['observations']:
        if o['domain'] is not None and domains.index(o['domain']) in sigdomains: continue
        expr=ve2(o['metric'],o['target']); cons.append(z3.And(expr>=L*o['lo'],expr<=L*o['hi']))
    sol=z3.Solver(); sol.add(cons); return sol

def study(seed):
    req=SF.gen(seed,mode='feasible'); norm=A.validate(req); B=prep(norm)
    k,faulty=get_k(B)
    if k is None:
        print(seed,'infeasible'); return
    domains=B['domains']; nd=B['nd']; ns=B['ns']; snaps=B['snaps']
    # active domains = appear in any observation
    active=set()
    for s in range(ns):
        for o in snaps[s]['observations']:
            if o['domain'] is not None: active.add(domains.index(o['domain']))
    active=sorted(active)
